import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.CDU0sSpB.js";const v=JSON.parse('{"title":"Phase 4 · Proactive Service and Mobile Entry","description":"Work proactively within limited authority and use the phone for approval and takeover.","frontmatter":{"title":"Phase 4 · Proactive Service and Mobile Entry","description":"Work proactively within limited authority and use the phone for approval and takeover.","outline":[2,3]},"headers":[],"relativePath":"en/delivery/stage-4.md","filePath":"en/delivery/stage-4.md","lastUpdated":1793859143000}'),i={name:"en/delivery/stage-4.md"};function n(h,e,d,s,l,c){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="phase-4-·-proactive-service-and-mobile-entry" tabindex="-1">Phase 4 · Proactive Service and Mobile Entry <a class="header-anchor" href="#phase-4-·-proactive-service-and-mobile-entry" aria-label="Permalink to &quot;Phase 4 · Proactive Service and Mobile Entry&quot;">​</a></h1><h2 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to &quot;Goal&quot;">​</a></h2><p>Phase 4 lets Hearth work proactively within limited authority and turns the phone into an entry for viewing, approval, and takeover. The point is not automatic running; it is doing the right thing at the right time without creating noise.</p><p>This phase has four steps:</p><table tabindex="0"><thead><tr><th>Step</th><th>Goal</th></tr></thead><tbody><tr><td><a href="/hearth-os/en/delivery/stage-4/4-1.html">4.1 Set triggers and proactive suggestions</a></td><td>Find work worth doing and explain why it matters now.</td></tr><tr><td><a href="/hearth-os/en/delivery/stage-4/4-2.html">4.2 Build the proactive inbox</a></td><td>Gather suggestions where they are easy to judge and handle.</td></tr><tr><td><a href="/hearth-os/en/delivery/stage-4/4-3.html">4.3 View, approve, and take over on the phone</a></td><td>Keep only key actions and short-lived authority on the phone, revocable if lost.</td></tr><tr><td><a href="/hearth-os/en/delivery/stage-4/4-4.html">4.4 Control interruption and accept proactive service</a></td><td>Proactive mode must be quiet, useful, controllable, and easy to turn off.</td></tr></tbody></table><h2 id="how-to-do-it" tabindex="-1">How to do it <a class="header-anchor" href="#how-to-do-it" aria-label="Permalink to &quot;How to do it&quot;">​</a></h2><ol><li>First create triggers and proactive suggestions without automatic execution.</li><li>Then gather suggestions in a proactive inbox where the user can accept, ignore, or turn them into tasks.</li><li>Then deliver the phone entry for viewing, approval, and takeover.</li><li>Finally accept with an attention budget and real tasks so proactive mode stays quiet, controllable, and revocable.</li></ol>',7)])])}const u=t(i,[["render",n]]);export{v as __pageData,u as default};
